"""Entry program for make.fun bounty news-image-20261117.

Writes the 17 November 2026 world-news image to /output/entry.png.
Deterministic, no network: the image is embedded below as base64 and
decoded on run, so the repository holds no binary file.
"""
import base64
import os

IMAGE_B64 = ""

def main():
    os.makedirs("/output", exist_ok=True)
    dst = os.path.join("/output", "entry.png")
    with open(dst, "wb") as f:
        f.write(base64.b64decode(IMAGE_B64))
    print("wrote %s (%d bytes)" % (dst, os.path.getsize(dst)))


if __name__ == "__main__":
    main()
